---
/**
 * Squishy text input. Variants map 1:1 to the `.input-*` classes in global.css.
 *
 *   <InputField variant="dark" placeholder="Name" />
 *   <InputField><Icon name="user" /></InputField>   // with icon
 *
 * With a slot (icon), the class goes on a wrapping <label>; without a slot it
 * goes on the <input> itself. `focus-within` in the CSS handles both.
 */
export const variants = {
  light: 'input-light',
  dark: 'input-dark',
} as const;

export type InputVariant = keyof typeof variants;

/** md = base size (no extra class), lg = 60px high like btn-lg */
export const inputSizes = { md: '', lg: 'input-lg' } as const;
export type InputSize = keyof typeof inputSizes;

interface Props {
  variant?: InputVariant;
  size?: InputSize;
  type?: 'text' | 'password' | 'email' | 'search' | 'number' | 'url';
  name?: string;
  placeholder?: string;
  value?: string;
  disabled?: boolean;
  class?: string;
}

const {
  variant = 'light',
  size = 'md',
  type = 'text',
  name,
  placeholder,
  value,
  disabled = false,
  class: className,
} = Astro.props;

const hasIcon = Astro.slots.has('default');
const attrs = { type, name, placeholder, value, disabled };
const classes = [variants[variant], inputSizes[size] || null, className];
---

{
  hasIcon ? (
    <label class:list={classes}>
      <slot />
      <input {...attrs} />
    </label>
  ) : (
    <input {...attrs} class:list={classes} />
  )
}

---
/** Multi-line text field. Uses the same variants as InputField. */
import { variants, inputSizes, type InputVariant, type InputSize } from './InputField.astro';

interface Props {
  variant?: InputVariant;
  size?: InputSize;
  name?: string;
  placeholder?: string;
  value?: string;
  rows?: number;
  disabled?: boolean;
  class?: string;
}

const {
  variant = 'light',
  size = 'md',
  name,
  placeholder,
  value,
  rows = 4,
  disabled = false,
  class: className,
} = Astro.props;
---

<textarea
  name={name}
  placeholder={placeholder}
  rows={rows}
  disabled={disabled}
  class:list={[variants[variant], inputSizes[size] || null, 'input-area', className]}>{value}</textarea
>

---
/** Native select with the input look and a pixel chevron. */
import { variants, inputSizes, type InputVariant, type InputSize } from './InputField.astro';
import Icon from './Icon.astro';

interface Option {
  value: string;
  label: string;
}

interface Props {
  variant?: InputVariant;
  size?: InputSize;
  name?: string;
  options: Option[];
  value?: string;
  disabled?: boolean;
  class?: string;
}

const {
  variant = 'light',
  size = 'md',
  name,
  options,
  value,
  disabled = false,
  class: className = '',
} = Astro.props;
const fullWidth = /\bw-full\b/.test(className);
const isDark = variant !== 'light';
---

<div class:list={['relative inline-flex max-w-lg', fullWidth && 'w-full']}>
  <select
    name={name}
    disabled={disabled}
    class:list={[variants[variant], inputSizes[size] || null, 'input-select', className]}
  >
    {
      options.map((o) => (
        <option value={o.value} selected={o.value === value}>
          {o.label}
        </option>
      ))
    }
  </select>
  <Icon
    name="keyboard-arrow-down"
    class:list={[
      'pointer-events-none absolute top-1/2 right-4 -translate-y-1/2',
      size === 'lg' ? 'size-8' : 'size-6',
      isDark
        ? 'text-white drop-shadow-[3px_3px_0_rgba(0,0,0,.5)]'
        : 'text-zinc-800',
    ]}
  />
</div>

---
/**
 * Number stepper: minus button, number, plus button.
 *   <Stepper name="qty" min={0} max={99} value={1} color="green" />
 */
import Button from './Button.astro';
import Icon from './Icon.astro';
import type { ColorName } from './palette';

interface Props {
  name?: string;
  min?: number;
  max?: number;
  step?: number;
  value?: number;
  color?: ColorName;
  disabled?: boolean;
  class?: string;
}

const {
  name,
  min = 0,
  max = 100,
  step = 1,
  value = 0,
  color = 'zinc',
  disabled = false,
  class: className,
} = Astro.props;
---

<div class:list={['stepper', className]} data-stepper>
  <Button as="button" icon color={color} aria-label="Decrease" data-step="-1" disabled={disabled || value <= min}>
    <Icon name="remove" />
  </Button>
  <input type="number" name={name} min={min} max={max} step={step} value={value} disabled={disabled} aria-label="Value" />
  <Button as="button" icon color={color} aria-label="Increase" data-step="1" disabled={disabled || value >= max}>
    <Icon name="add" />
  </Button>
</div>

<script>
  function sync(root: HTMLElement) {
    const input = root.querySelector('input')!;
    const v = Number(input.value);
    const min = input.min === '' ? -Infinity : Number(input.min);
    const max = input.max === '' ? Infinity : Number(input.max);
    root.querySelector<HTMLButtonElement>('[data-step="-1"]')!.disabled = input.disabled || v <= min;
    root.querySelector<HTMLButtonElement>('[data-step="1"]')!.disabled = input.disabled || v >= max;
  }

  document.addEventListener('click', (e) => {
    const btn = (e.target as HTMLElement).closest<HTMLButtonElement>('[data-stepper] [data-step]');
    if (!btn) return;
    const root = btn.closest<HTMLElement>('[data-stepper]')!;
    const input = root.querySelector('input')!;
    if (Number(btn.dataset.step) > 0) input.stepUp();
    else input.stepDown();
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.dispatchEvent(new Event('change', { bubbles: true }));
  });

  document.addEventListener('input', (e) => {
    const root = (e.target as HTMLElement).closest<HTMLElement>('[data-stepper]');
    if (root) sync(root);
  });

  document.querySelectorAll<HTMLElement>('[data-stepper]').forEach(sync);
</script>
